src='''def transform(grid):
    g=[r[:] for r in grid]; h=len(g); w=len(g[0])
    # Ray from each colored seed toward edge marker; seed changes to 4.
    # For 7s and left-edge 3 bar, draw 7 leftward.
    for r in range(h):
        for c in range(w):
            if grid[r][c]==7:
                g[r][c]=4
                if any(grid[r][k]==3 for k in range(c)):
                    for k in range(c):
                        if grid[r][k]!=3: g[r][k]=7
                elif any(grid[r][k]==3 for k in range(c+1,w)):
                    for k in range(c+1,w):
                        if grid[r][k]!=3: g[r][k]=7
    # A 3 boundary segment without seeds creates a 7 stroke on its central row.
    for side in (0,w-1):
        rows=[r for r in range(h) if grid[r][side]==3]
        if rows:
            mid=(min(rows)+max(rows))//2
            if not any(grid[mid][c]==7 for c in range(w)):
                for c in range(w):
                    if grid[mid][c]!=3: g[mid][c]=7
    return g
